// Крупные группы (те же id, что в миграции 20261105120000_catalog_groups).
const GROUPS = [{"id": "a0000000-0000-4000-8000-000000000001", "name": {"ru": "Фрукты и ягоды", "kk": "Жемістер мен жидектер", "en": "Fruit & berries"}, "subs": ["Цитрусовые", "Яблоки", "Груши", "Виноград", "Косточковые", "Бахчевые", "Хурма", "Бананы", "Авокадо", "Ананасы", "Гранаты", "Манго", "Киви", "Экзотические фрукты", "Ягоды"]}, {"id": "a0000000-0000-4000-8000-000000000002", "name": {"ru": "Овощи и зелень", "kk": "Көкөністер мен көкөніс шөптері", "en": "Vegetables & greens"}, "subs": ["Томаты", "Огурцы", "Перцы", "Овощи", "Корнеплоды", "Зелень и салаты", "Грибы"]}, {"id": "a0000000-0000-4000-8000-000000000003", "name": {"ru": "Салаты и соленья", "kk": "Салаттар мен тұздықтар", "en": "Salads & pickles"}, "subs": ["Корейские салаты", "Соленья и квашеное"]}, {"id": "a0000000-0000-4000-8000-000000000004", "name": {"ru": "Орехи и сухофрукты", "kk": "Жаңғақтар мен кептірілген жемістер", "en": "Nuts & dried fruit"}, "subs": ["Орехи", "Финики и сухофрукты"]}, {"id": "a0000000-0000-4000-8000-000000000005", "name": {"ru": "Молочка и яйца", "kk": "Сүт өнімдері мен жұмыртқа", "en": "Dairy & eggs"}, "subs": ["Молочная продукция", "Яйца"]}, {"id": "a0000000-0000-4000-8000-000000000006", "name": {"ru": "Мясо и рыба", "kk": "Ет пен балық", "en": "Meat & fish"}, "subs": ["Мясо и птица", "Рыба и морепродукты", "Колбасы и деликатесы"]}, {"id": "a0000000-0000-4000-8000-000000000007", "name": {"ru": "Мёд и сладости", "kk": "Бал мен тәттілер", "en": "Honey & sweets"}, "subs": ["Мёд и варенье", "Конфеты и шоколад", "Печенье и восточные сладости", "Снеки и семечки"]}, {"id": "a0000000-0000-4000-8000-000000000008", "name": {"ru": "Хлеб и выпечка", "kk": "Нан және тоқаш", "en": "Bread & bakery"}, "subs": ["Хлеб и лепёшки", "Выпечка и торты"]}, {"id": "a0000000-0000-4000-8000-000000000009", "name": {"ru": "Бакалея", "kk": "Бакалея", "en": "Pantry"}, "subs": ["Крупы и бобовые", "Макароны и лапша", "Мука, сахар, соль", "Масло растительное", "Специи и приправы", "Соусы и консервы"]}, {"id": "a0000000-0000-4000-8000-00000000000a", "name": {"ru": "Чай, кофе, напитки", "kk": "Шай, кофе, сусындар", "en": "Tea, coffee & drinks"}, "subs": ["Чай и кофе", "Вода и напитки"]}, {"id": "a0000000-0000-4000-8000-00000000000b", "name": {"ru": "Замороженное", "kk": "Мұздатылған өнімдер", "en": "Frozen"}, "subs": ["Полуфабрикаты", "Замороженные овощи и ягоды", "Мороженое"]}, {"id": "a0000000-0000-4000-8000-00000000000c", "name": {"ru": "Для дома", "kk": "Үйге арналған", "en": "Household"}, "subs": ["Бытовая химия", "Бумажные товары и гигиена"]}];
function groupFor(ru) { return GROUPS.find((g) => g.subs.includes(ru)); }

async function findCategory(ru) {
  return prisma.category.findFirst({ where: { name: { path: ['ru'], equals: ru } }, select: { id: true } });
}
async function findProduct(categoryId, ru) {
  return prisma.masterProduct.findFirst({ where: { categoryId, name: { path: ['ru'], equals: ru } }, select: { id: true } });
}

(async () => {
  let cCreated = 0, pCreated = 0, pSkipped = 0;
  try {
    let renamed = 0;
    for (const [catRu, from, to] of RENAMES) {
      const cat = await findCategory(catRu);
      const p = cat && (await findProduct(cat.id, from));
      if (p && !(await findProduct(cat.id, to))) {
        await prisma.masterProduct.update({ where: { id: p.id }, data: { name: nameOf(to, I18N.products) } });
        renamed++;
      }
    }
    if (renamed) console.log(`Переименовано товаров: ${renamed}.`);
    for (let i = 0; i < DATA.length; i++) {
      const g = DATA[i];
      const group = groupFor(g.cat);
      if (group) {
        await prisma.category.upsert({
          where: { id: group.id },
          update: {},
          create: { id: group.id, name: group.name, sort: GROUPS.indexOf(group) },
        });
      }
      let cat = await findCategory(g.cat);
      if (!cat) {
        cat = await prisma.category.create({
          data: { name: nameOf(g.cat, I18N.categories), perishable: !!g.perishable, coldChain: !!g.coldChain, sort: i, parentId: group ? group.id : null },
          select: { id: true },
        });
        cCreated++;
      } else if (group) {
        await prisma.category.updateMany({ where: { id: cat.id, parentId: null }, data: { parentId: group.id } });
      }
      for (const raw of g.items) {
        const it = typeof raw === 'string' ? { n: raw } : raw;
        const unit = it.u || g.u || 'KG';
        if (await findProduct(cat.id, it.n)) { pSkipped++; continue; }
        await prisma.masterProduct.create({
          data: {
            categoryId: cat.id,
            name: nameOf(it.n, I18N.products, OVERRIDES[`${g.cat}/${it.n}`]),
            unit,
            stepG: unit === 'KG' || unit === 'G' ? (it.step || g.step || 500) : null,
            avgPieceG: unit === 'PCS' ? (it.avg || null) : null,
            perishable: !!g.perishable,
            storage: g.coldChain ? 'Хранить в холоде' : null,
          },
        });
        pCreated++;
      }
    }
    console.log(`Готово. Категорий создано: ${cCreated}. Товаров создано: ${pCreated}, пропущено (уже были): ${pSkipped}.`);
  } catch (e) {
    console.error('Ошибка:', e.message);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
})();
